package main

import (
	"log"
	"net/http"
	"os"

	"usersvc/internal/user"
)

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "18080"
	}

	store := user.NewStore()
	store.Seed(user.User{Email: "exists@test.co", Name: "Seed"})

	mux := http.NewServeMux()
	user.NewHandler(store).Register(mux)

	log.Printf("users service listening on 127.0.0.1:%s", port)
	log.Fatal(http.ListenAndServe("127.0.0.1:"+port, mux))
}

package user

import (
	"errors"
	"sync"
)

var (
	ErrNotFound   = errors.New("user not found")
	ErrEmailTaken = errors.New("email already used")
)

type User struct {
	ID    int64  `json:"id"`
	Email string `json:"email"`
	Name  string `json:"name"`
}

// Store keeps users in memory for local dev; Postgres comes later.
type Store struct {
	mu      sync.Mutex
	nextID  int64
	users   map[int64]User
	byEmail map[string]int64
}

func NewStore() *Store {
	return &Store{nextID: 1, users: map[int64]User{}, byEmail: map[string]int64{}}
}

func emailKey(email string) string { return email }

func (s *Store) Seed(u User) { _, _ = s.Create(u) }

func (s *Store) Create(u User) (User, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.byEmail[emailKey(u.Email)]; ok {
		return User{}, ErrEmailTaken
	}
	u.ID = s.nextID
	s.nextID++
	s.users[u.ID] = u
	s.byEmail[emailKey(u.Email)] = u.ID
	return u, nil
}

func (s *Store) Get(id int64) (User, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	u, ok := s.users[id]
	if !ok {
		return User{}, ErrNotFound
	}
	return u, nil
}

// Update changes only the fields that are not nil (partial update).
func (s *Store) Update(id int64, email, name *string) (User, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	u, ok := s.users[id]
	if !ok {
		return User{}, ErrNotFound
	}
	if email != nil {
		if other, ok := s.byEmail[emailKey(*email)]; ok && other != id {
			return User{}, ErrEmailTaken
		}
		delete(s.byEmail, emailKey(u.Email))
		u.Email = *email
		s.byEmail[emailKey(u.Email)] = id
	}
	if name != nil {
		u.Name = *name
	}
	s.users[id] = u
	return u, nil
}

// Delete removes the user for good (hard delete, per legal).
func (s *Store) Delete(id int64) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	u, ok := s.users[id]
	if !ok {
		return ErrNotFound
	}
	delete(s.byEmail, emailKey(u.Email))
	return nil
}

package user

import (
	"encoding/json"
	"errors"
	"net/http"
	"regexp"
	"strconv"
	"strings"
)

var emailRe = regexp.MustCompile(`^[^@\s]+@[^@\s]+\.[^@\s]+$`)

type Handler struct{ store *Store }

func NewHandler(s *Store) *Handler { return &Handler{store: s} }

func (h *Handler) Register(mux *http.ServeMux) {
	mux.HandleFunc("GET /users/{id}", h.get)
	mux.HandleFunc("POST /users", h.create)
}

type createRequest struct {
	Email string `json:"email"`
	Name  string `json:"name"`
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

func writeError(w http.ResponseWriter, status int, msg string) {
	writeJSON(w, status, map[string]string{"error": msg})
}

// pathID parses {id}. A non-numeric id is "not found" (mobile wants 404, not 400).
func pathID(r *http.Request) (int64, bool) {
	id, err := strconv.ParseInt(r.PathValue("id"), 10, 64)
	return id, err == nil && id > 0
}

func (h *Handler) get(w http.ResponseWriter, r *http.Request) {
	id, ok := pathID(r)
	if !ok {
		writeError(w, http.StatusNotFound, ErrNotFound.Error())
		return
	}
	u, err := h.store.Get(id)
	if err != nil {
		writeError(w, http.StatusNotFound, err.Error())
		return
	}
	writeJSON(w, http.StatusOK, u)
}

func (h *Handler) create(w http.ResponseWriter, r *http.Request) {
	var req createRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "invalid json")
		return
	}
	if !emailRe.MatchString(req.Email) {
		writeError(w, http.StatusBadRequest, "invalid email")
		return
	}
	if strings.TrimSpace(req.Name) == "" {
		writeError(w, http.StatusBadRequest, "name required")
		return
	}
	u, err := h.store.Create(User{Email: req.Email, Name: req.Name})
	if errors.Is(err, ErrEmailTaken) {
		writeError(w, http.StatusConflict, err.Error())
		return
	}
	writeJSON(w, http.StatusCreated, u)
}

